#include <execinfo.h>

static void kicad_headless_gui_stub( const char* aSymbol )
{
    std::fprintf( stderr,
                  "\nkicad-api-host: %s was called in a headless build.\n"
                  "The caller below is missing its KICAD_HEADLESS_API guard.\n",
                  aSymbol );

    void* frames[32];
    int   count = backtrace( frames, 32 );
    backtrace_symbols_fd( frames, count, 2 );
    std::abort();
}

/// Name the stub by its mangled symbol, so that the definition *is* the missing function.
#define KI_HEADLESS_STUB( index, mangled, readable )                      \
    extern "C" __attribute__( ( visibility( "default" ) ) ) void ki_headless_stub_##index()  \
            __asm__( mangled );                                                            \
    extern "C" void ki_headless_stub_##index() { kicad_headless_gui_stub( readable ); }


